from pathlib import Path
import json,re,hashlib
BASE=Path(__file__).resolve().parent
OUT=BASE/'proposed-items'
RUN='non-ml-math-remaining-81-2026-10-18'
AC='def-axiom-of-choice'
ISO='lem-isotopy-extension-for-a-compact-source-with-boundary'
CISO='lem-a-smooth-isotopy-of-compact-embedded-submanifolds-extends-to-an-ambient-isotopy'
ROUND='lem-smooth-handle-attachment-is-independent-of-corner-rounding-up-to-diffeomorphism'
FLOW='thm-compactly-supported-time-dependent-vector-fields-have-global-evolution-on-a-compact-time-interval'
COLLAR='thm-collar-neighborhood-theorem'
TRANS='thm-parametric-transversality'
APPROX='thm-relative-whitney-approximation-for-manifold-valued-maps'
WHITNEY='thm-whitney-approximation-for-manifold-valued-maps'
FRAME='lem-a-normal-summand-of-rank-at-least-two-surjects-on-the-framing-loop-obstruction'
CIRCLE='lem-framed-circles-in-four-dimensional-two-handle-traces-move-to-the-base'
TRADE='lem-interior-one-handle-trade-and-framed-circle-surgery-pair'
MORSE='lem-fixed-vertical-height-relative-morse-handle-normalization'
SURGERY='lem-relative-three-manifolds-admit-parametrized-link-surgery-presentations'
MIDDLE='lem-boundary-marked-five-bordisms-give-common-middle-two-handle-traces'
OMEGA3='thm-every-closed-oriented-smooth-three-manifold-bounds-a-compact-oriented-smooth-four-manifold'
O3='lem-circumcision-meridian-pair-preserves-relative-three-manifold'
ROBERTS='https://arxiv.org/pdf/math/9812086'
ITEMS=[]
def item(id,title,statement,facts,steps,scope):
 deps=list(dict.fromkeys([AC]+[x for fact in facts for x in re.findall(r'\[\[([^]|]+)',fact)]))
 meta='---\nid: '+id+'\nkind: lemma\ntitle: '+json.dumps(title)+'\nstatus: draft\norigin: pipeline\npipeline_run: '+RUN+'\nproof_strategy: direct\nprovenance:\n  statement: literature-derived\n  proof: ai-altered\ndeps: '+json.dumps(deps)+'\njustified_by: []\nsources:\n  references:\n    - title: "Justin Roberts, Kirby calculus in manifolds with boundary"\n      url: '+ROBERTS+'\n      locator: "Stage 1 and relative handle setup; the full local constructions are supplied in this proof, rather than assuming surgery or Kirby completeness."\n---\n'
 text=meta+'\n## Statement\n\nAssume AC. '+statement+'\n\n## Facts & Assumptions\n\n**Given:** The manifolds, collars, framed embeddings and boundary identifications in the Statement; AC ([['+AC+']]).\n\n'+'\n\n'.join('[F'+str(i+1)+'] '+f for i,f in enumerate(facts))+'\n\n## Proof\n\n**Proof technique:** Direct constructions in product collars, retaining the actual boundary maps.\n\n'+'\n\n'.join(number+' '+body+' ['+tags+']'+(' ∎' if j==len(steps)-1 else '') for j,(number,body,tags) in enumerate(steps))+'\n\n## Scope and source attribution\n\n'+scope+'\n'
 p=OUT/(id+'.md');p.write_text(text);ITEMS.append(p)

item(CIRCLE,'Framed circles in a four-dimensional two-handle trace move to its fixed base',r'''Let $N$ be a connected nonempty compact smooth oriented three-manifold, and let $W$ be a finite four-dimensional two-handle trace from $N$, with its full external boundary collar fixed. Every smooth framed circle in $\operatorname{int}W$ avoiding that protected collar is ambiently isotopic, with compact support outside it, to a circle in a pushed-in copy of $N$. The target circle may avoid the old finite attaching link. Its prescribed oriented rank-three normal framing is represented, up to homotopy and isotopy of its small tubular attaching embedding, by an integral rank-two framing in $N$ plus the level-normal line. No condition on $\pi_1(N)$ or on the circle's class is imposed. More generally, freely homotopic embedded circles in a smooth manifold of dimension $d\ge4$ are isotopic whenever their homotopy lies in a prescribed relatively compact open set; the isotopy may be supported in that set. Every loop class in a three-manifold has an embedded representative avoiding a prescribed finite link.''',[
 '[['+APPROX+']] smooths a homotopy relative to a neighborhood of its stationary endpoints. The actual proof of [['+WHITNEY+']] supplies a finite-dimensional Euclidean embedding of the target and a smooth neighborhood retraction; those constructed data are used below.',
 '[['+TRANS+']] gives a null set of bad parameters when the full finite-dimensional evaluation is transverse. The polynomial interpolation used to make that evaluation submersive is proved below.',
 '[['+CISO+']] extends compact circle isotopies with prescribed neighborhood support. [['+ISO+']] applies to compact full-dimensional tubular product embeddings with boundary in the boundaryless interior. [['+FLOW+']] gives their supported smooth ambient flows.',
 '[[thm-seifert-van-kampen]] identifies the group of a handle attachment as the pushout of the old stage and a contractible handle over the connected attaching region.',
 '[['+FRAME+']] states that $SO(2)\to SO(3)$ surjects on fundamental groups and proves it by a Stiefel disk filling and complement-frame transport. [['+COLLAR+']] supplies the collars used to push auxiliary homotopies into the interior.'
],[
 ('1.1',r'''First take embedded endpoint circles in a $d$-manifold, $d\ge4$, and a continuous free homotopy with compact image in a prescribed relatively compact open set $O$. Reparametrize it to be constant near both endpoints, extend constantly to an open parameter interval, and apply [F1] there relative to closed endpoint neighborhoods. Restriction gives a smooth homotopy $H:[0,1]\times S^1\to O$ with the specified stationary ends. Write $j:O\to\mathbb R^a$ and $R:U\to j(O)$ for the embedding and retraction constructed in [F1]. Along the compact image, $dR$ has rank $d$ because $R$ fixes $j(O)$; retain a uniform neighborhood with that rank.''','given, F1, construct'),
 ('1.2',r'''Let $e:S^1\to\mathbb R^2$ be the round embedding. Polynomials of degree at most three in its two coordinates prescribe values and first derivatives independently at any two distinct points. Indeed choose affine $\lambda$ zero at the second point and nonzero at the first; multiply a suitable affine Taylor polynomial by $\lambda^2$ to prescribe the first jet at the first while killing it at the second. Interchanging the points and adding gives arbitrary first jets at both. Along a single circle point its tangent derivative can therefore also be prescribed. For a polynomial basis $P_\nu$, ambient coordinate vectors $e_\alpha$, and a smooth $\beta(s)$ zero near the ends and positive elsewhere, define $H_z(s,t)=j^{-1}R(jH(s,t)+\beta(s)\sum_{\nu,\alpha}z_{\nu\alpha}P_\nu(e(t))e_\alpha)$. Small parameters keep the compact image in $O$. This is submersive on the needed value/first-jet evaluations at one or two distinct points: first prescribe ambient value variations, then derivative variations to cancel the extra derivative-of-$dR$ terms, and apply the surjective $d(j^{-1}R)$.''','F1, step 1.1, construct, algebra'),
 ('1.3',r'''The zero-velocity stratum of the curve one-jet bundle has codimension $d$ on the two-dimensional source $(s,t)$. The diagonal of $O\times O$ has codimension $d$ on the three-dimensional same-parameter source $(s,t,t')$, $t\ne t'$. By [F2] one small parameter avoids both strata: their transverse inverse images have negative dimension, since $d\ge4$. The noncompact off-diagonal source is permitted by [F2]; it need not be replaced by a compact configuration space. Endpoint neighborhoods are stationary. Compact-circle embedding is open in the $C^1$ topology: finitely many coordinate intervals give a positive local derivative bound and injectivity on shorter intervals, and pairs outside those intervals have positive image separation. Smallness retains the endpoint embedding condition in transition collars. Every slice is thus injective and immersive; compactness makes it an embedding. Its compact track lies in $O$, so [F3] gives an ambient isotopy supported in a compact subset of $O$.''','F2, F3, step 1.2, construct'),
 ('1.4',r'''Without the homotopy parameter the same family proves the three-dimensional assertion. Smooth the continuous loop by [F1]. The nonimmersion source now has dimension one and the double-point source dimension two, both below the respective codimension three. To avoid a finite old link add the evaluation transversality condition to each component: its codimension is two and the loop source has dimension one. The value-submersive family in step 1.2 handles all finitely many conditions simultaneously. One small parameter therefore gives an embedded representative of the original free class disjoint from that link.''','F1, F2, step 1.2, construct'),
 ('2.1',r'''For a single two-handle use open thickenings of the old stage and the handle. Their overlap retracts onto $S^1\times D^2$ and is connected, whereas the handle thickening is contractible. By [F4] the new fundamental group is the old group modulo the normal closure of the attaching-circle class. Finite induction gives a surjection $\pi_1(N)\to\pi_1(W)$. Hence the given interior circle is freely homotopic to a loop in a pushed-in base copy. Step 1.4 gives an embedded representative there avoiding the old attaching link. This uses the arbitrary group class, not nullhomotopy.''','F4, step 1.4, construct'),
 ('2.2',r'''The auxiliary homotopy may be pushed off the protected external collar while keeping its endpoints. If that strip has inward coordinate $r\le a$, choose $\delta>0$ so both endpoint loops avoid $r\le a+2\delta$. On $[0,a+2\delta]$ use an increasing smooth map into $[a+\delta,a+2\delta]$ agreeing with identity near its upper end, and extend by identity beyond. Its composition with the homotopy changes only that auxiliary map, not $W$ or its prescribed collars. The image is compact and misses the protected strip. Choose a relatively compact open neighborhood of this image outside the strip and apply step 1.3. This gives the required supported ambient isotopy. Without the stated endpoint-avoidance hypothesis it only guarantees avoidance of a sufficiently small boundary strip, so that hypothesis is retained in the Statement.''','F5, step 1.3, step 2.1, construct'),
 ('3.1',r'''Transport the prescribed rank-three normal frame by the ambient isotopy. At the base circle its normal bundle splits into the oriented rank-two normal bundle in $N$ and the level-normal line. An oriented bundle on a circle is trivial: transport a frame around a cut interval and correct endpoint holonomy by a path in the orientation-preserving linear group, using orthonormalization and plane rotations. Choose an initial level frame. Its rank-three extension differs from the prescribed frame by a loop in $GL^+(3,\mathbb R)$, which polar orthonormalization retracts to $SO(3)$. By [F5] its class comes from $SO(2)$. Modify the level frame by that loop; this is an integral twist, and its rank-three extension is now homotopic to the prescribed frame. This retains both possible rank-three framing classes rather than equating them.''','F5, step 2.2, construct, algebra'),
 ('3.2',r'''A smooth homotopy of the frames gives an isotopy of sufficiently small tubular product embeddings. In a fixed normal chart apply the invertible frame maps to the disk coordinates; compactness of the parameter-circle product gives one radius on which all are embedded. The full-dimensional compact-source version of [F3], applied in the boundaryless interior after stationary endpoint reparametrization, extends this isotopy while fixing the external collar. Thus the conclusion retains the whole framed attaching embedding and not merely its unframed core. Together with steps 1.1–2.2 this proves every clause.''','F3, step 1.3, step 1.4, step 2.2, step 3.1, construct')
],r'''The full accepted construction in `circles-in-four-dimensional-traces.md`, Sections 1–3, is retained here, with its finite polynomial family and framing parity. Section 4 of that proposal is a consumer of the separate disk-factor bridge and is not used as a premise here. The actual full authored Whitney, van Kampen, framing-loop, transversality and compact isotopy-extension suppliers were read. Roberts supplies context, not a replacement for this proof or a Kirby-completeness premise.''')

item(TRADE,'Interior one-handle trades and the fully framed circle-surgery pair',r'''In dimension $d\ge4$, a one-handle whose feet lie in the same connected lower stage can be replaced, by an interior framed circle surgery, with one $(d-2)$-handle. The resulting manifold may change, but its entire boundary, specified collar and every later attaching map are identified with the old ones. The framing for this existence trade is the displayed product framing. Separately, surgery on a prescribed rank-three-framed circle lying in a product three-dimensional level of an oriented four-manifold, with its framing homotopic to a level rank-two framing plus the level-normal line, is represented relative to the unaffected boundary by adjoining two four-dimensional two-handles on that framed knot $K$ and a small disk-framed zero meridian $U$. The statement retains the integral framing of $K$. In a two-handle trace every interior framed circle can be put in this form by the preceding circle lemma. The pair's boundary identification is the boundary-relative local O3 identification.''',[
 '[['+ISO+']] compares isotopies of the full compact tubular attaching embeddings; [['+ROUND+']] compares compatible seam roundings by collar-supported diffeomorphisms.',
 '[['+CIRCLE+']] moves an interior framed circle of a four-dimensional two-handle trace to a pushed-in fixed base, disjoint from the old link, retaining the prescribed rank-three framing through an integral level framing.',
 '[['+O3+']] gives the actual boundary-relative solid-torus diffeomorphism for a framed core and its disk-framed zero meridian. It fixes the old link and external collars when their supports avoid that torus.',
 '[[lem-boundary-connected-sum-with-a-disk-does-not-change-the-diffeomorphism-type]] absorbs a ball attached along a boundary disk by a diffeomorphism supported in its collar.'
],[
 ('1.1',r'''Join the feet of the one-handle by an embedded arc in the connected lower stage, with interior away from the feet, and thicken it. Along with the handle core this gives a standard ball-plus-tube neighborhood $S^1\times D^{d-1}$, with a designated $(d-1)$-ball on its boundary in the lower stage. Concretely thicken the joining arc to a disk tube, use the foot disks as its ends, and join the second tube supplied by the handle. Match their endpoint normal coordinates to obtain exactly this product, and push the core circle into its interior.''','given, construct'),
 ('1.2',r'''Interior surgery replaces a smaller $S^1\times D^{d-1}$ by $D^2\times S^{d-2}$. The remaining shell of the original product is $S^1\times S^{d-2}\times I$, so it is a retained boundary collar. Split the sphere into its two hemispheres. The first $D^2\times D^{d-2}_+$ is a ball. The second, read with core factor $D^{d-2}_-$, is a $(d-2)$-handle with attaching region $D^2\times S^{d-3}$ and outgoing region $S^1\times D^{d-2}_-$. Place the designated lower-stage boundary ball in $S^1\times\operatorname{int}D^{d-2}_+$, which is on the first ball's boundary. Absorb that ball into the lower collar by [F4]. The remaining handle has index $d-2$. The outer collar is unchanged point by point; every later attachment is carried by that boundary identification. This is an interior modification, not a cancellation of the original ambient manifold. For $d=4$ it trades index one for two, and for $d=5$ one for three; reversing dimension five gives index four to two.''','F1, F4, step 1.1, construct'),
 ('2.1',r'''For the four-dimensional bridge choose coordinates $S^1\times D^3$ about the level circle, with $D^2_{\mathrm{eq}}$ the level equator and lower/upper half-balls $D^3_-,D^3_+$. Remove this tube and insert $D^2_a\times S^2$, using its given full rank-three framing. Split $S^2=S^2_-\cup_{S^1_{\mathrm{eq}}}S^2_+$. The lower product with $S^1\times D^3_-$ removed is a product collar with an indented outgoing face: in the normal coordinates the half-ball removal moves the old upper face to an inward rounded graph. A smooth increasing interval map on each normal line, fixed at the lower end, carries that face to the graph; these maps are identity outside the tube and the seam rounding is in a smaller collar. The upper half has the same product description. Thus the surgery is a product, the two inserted pieces, and an absorbable outgoing product.''','F1, construct'),
 ('2.2',r'''The first piece $D^2_a\times S^2_-$ is a two-handle with core $D^2_a$, normal disk $S^2_-$ and attaching region $S^1_a\times S^2_-$. On the old level this is the knot $K$ with its prescribed level framing. Its outgoing region is $D^2_a\times S^1_{\mathrm{eq}}$. The second piece $D^2_a\times S^2_+$ is also a two-handle, but its disk factors are interchanged: core $S^2_+$, normal disk $D^2_a$, attaching region $D^2_a\times S^1_{\mathrm{eq}}$. This is exactly the outgoing region of the first handle; using the same core factor for both would give a different attaching region.''','step 2.1, construct'),
 ('2.3',r'''The second attaching circle is $\{p\}\times S^1_{\mathrm{eq}}$ for an interior point $p\in D^2_a$. Move $p$ along a radial arc toward $S^1_a$, first shrinking its normal thickening uniformly. This is a compact isotopy of the actual attaching product embedding in the boundary after the first handle. At the seam its product corner rotation carries it to the old level, where it is a small meridian of $K$. Its tangential $S^1_a$ direction is a constant push direction around this meridian and its other normal direction is the complementary radial direction in $D^2_{\mathrm{eq}}$. Thus its framing has no turn relative to the meridian disk, so is zero. Its other boundary piece $S^1_a\times S^2_+$ is where the indented upper product attaches. Absorbing that product retains the original upper boundary map. By [F1] these product isotopies compare the full handle attachments, not just their cores.''','F1, step 2.2, construct'),
 ('3.1',r'''For an arbitrary prescribed rank-three frame on a circle in a two-handle trace, [F2] first moves the circle to the base and realizes its framing by an integral level frame. Its framing homotopy is realized by an isotopy of small tubular embeddings, so steps 2.1–2.3 apply to the prescribed surgery relative to the whole ambient boundary. By [F3] the resulting pair has the O3 boundary-relative identification on its small solid torus; old attaching links outside that torus and external base collars are fixed. This proves the bridge for every framing, without identifying the two rank-three parity classes, as well as the existence trade in steps 1.1–1.2.''','F1, F2, F3, step 1.2, step 2.3, construct')
],r'''This retains the full two-hemisphere construction and essential second-factor swap in `five-dimensional-common-middle-trace-construction.md`, Sections 1–3. The compact embedding, corner-rounding, disk-absorption and local O3 suppliers were read in full. The local trade chooses its product framing; only the separate four-dimensional bridge handles an arbitrary prescribed framing. No uniqueness of four-dimensional trace presentations or completeness of O2/O3 is assumed.''')
item(MORSE,'Relative Morse handle normalization with the full vertical height fixed',r'''Let $d\ge4$, and let $V$ be a compact smooth $d$-dimensional bordism with corners, horizontal faces $A_0,A_1$, and vertical face $B\times[0,1]$, with compatible product collar charts fixed. Here $\partial A_i=B\times\{i\}$. There are excellent Morse data with all critical points interior, equal to the specified height $t$ on a fixed smaller vertical product collar, zero and one on the horizontal faces with their prescribed inward collar models. They give a finite handle decomposition whose attaching thickenings lie in the interiors of horizontal levels, away from the fixed vertical collar, retaining the actual outgoing identification. Critical values may be ordered by index while this entire boundary height is fixed. If $V,A_0,A_1$ are connected and $A_0,A_1$ are nonempty, there is such a relative presentation with no handles of index zero or $d$. No fundamental-group assumption or h-cobordism hypothesis is imposed.''',[
 '[[thm-adapted-excellent-morse-functions-exist-on-compact-cobordisms]] gives the actual bump-supported finite differential-perturbation and local metric construction for compact ordinary triads. [['+TRANS+']] gives the finite-dimensional perturbation theorem. The vertical-face adaptation is constructed below, not presumed from the ordinary-triad statement.',
 '[[thm-every-smooth-manifold-admits-a-riemannian-metric]], [[thm-smooth-partitions-of-unity-exist-on-manifolds-with-boundary]], and [[lem-manifold-bump-for-a-compact-set-inside-an-open-set]] supply metrics and supported patching. [['+FLOW+']] and [[thm-fundamental-theorem-on-flows]] give complete supported flows and uniqueness.',
 '[[lem-handles-of-equal-index-can-be-attached-on-one-level]] supplies the local framed handle-band construction and isotopy invariance. [['+ROUND+']] supplies relative seam rounding.',
 '[[lem-gradient-like-perturbation-separates-adjacent-critical-levels]] supplies the interior crossing-sphere moving-off construction. [[lem-critical-values-of-disjoint-trajectory-closures-can-be-interchanged]] supplies its actual orbit-constant separating function and value-change formula. Their fixed-vertical-height extension is supplied below.',
 '[[prop-connected-cobordisms-admit-presentations-without-superfluous-zero-handles]] proves zero-handle removal by a rooted spanning tree and transport of later attaching maps. [[lem-boundary-connected-sum-with-a-disk-does-not-change-the-diffeomorphism-type]] supplies its collar-supported disk absorption. Below this construction is carried out away from the vertical collar.'
],[
 ('1.1',r'''In the fixed corner and face charts extend the boundary height by the inward horizontal collar coordinate near $A_0$, one minus that coordinate near $A_1$, and $t$ on the vertical collar. These agree in the specified product corner charts: the horizontal inward coordinate there is exactly $t$ or $1-t$. Patch only beyond smaller common collars using [F2], blending with $1/2$ in the compact interior. At a corner use restrictions of ordinary Euclidean bumps to its product quadrant; a finite cover and division by their positive sum give the required partition there. Thus the same finite patching proof applies directly to these corner charts, rather than presuming that a boundary-only partition statement already covers corners. The resulting smooth $h:V\to[0,1]$ has exactly the endpoint fibers $A_0,A_1$, is strictly between zero and one elsewhere, and has nonzero differential near every boundary face and corner. Thus the possible critical set lies in a compact subset of the ordinary interior.''','given, F2, construct'),
 ('1.2',r'''On that compact set choose finitely many nested interior coordinate charts and bump-supported linear coordinate functions, as in the actual proof of [F1]. Their differential evaluations span the cotangent fiber wherever a critical point is possible. The finite-dimensional evaluation is therefore transverse to the zero section. By [F1] choose an arbitrarily small parameter whose differential is transverse to zero. Compactness and nondegeneracy give finitely many critical points. Independent constant bumps separate their values without changing their Hessians, and the positive value margin on the perturbation support retains the range and endpoint fibers. The result is an excellent Morse function equal to the original height on all protected collars.''','F1, F2, step 1.1, construct'),
 ('1.3',r'''Choose the metric $dt^2+dr^2+g_B$ on the vertical collar, where $r$ is its inward normal coordinate, and Euclidean metrics on smaller disjoint critical charts; patch elsewhere by [F2]. The negative gradient is tangent to the vertical face and equals $-\partial_t$ there. It has the standard linear Morse model at each critical point and the required horizontal entry and exit signs. Extend it over signed face collars in the product models and cut it off on an ambient carrier. Its spatial modifications have compact support, so [F2] gives complete evolution. An interior trajectory cannot first hit the vertical face in finite time: the unique solution through a hypothetical first-hit point would lie in that boundary face backwards as well, contradicting its interior starting point.''','F2, step 1.2, construct'),
 ('2.1',r'''Transport framed local unstable disks across the regular bands by this boundary-tangent field. Their compact sphere sections lie away from the vertical collar. Outside small Morse blocks strict descent has a uniform positive lower bound on each compact band. In the blocks the exact exponential Morse flow accounts for infinite-time limits, which can occur only at critical points, never at the noncritical vertical model. Consequently every finite regular transport of a compact attaching thickening stays in a compact subset of the interior of a horizontal level. The local construction in [F3], with its product complement transported by the regular flow, therefore gives the finite relative handle decomposition. All handles attach away from the vertical collar, and the composed outgoing identification is retained. This proves the cornered interface directly; the ordinary closed-face theorem is not invoked outside its hypotheses.''','F2, F3, step 1.3, construct'),
 ('2.2',r'''For an inverted adjacent critical pair, the compact unstable and stable sphere sections in a regular $(d-1)$-level have dimensions summing to at most $d-2$. The moving-off construction in [F4] uses product tubes and arbitrarily small translations of these compact sections, avoiding the finite projected lower-dimensional sets simultaneously. Choose these tubes inside that level's interior. Its regular-band field shear thus separates the sections with support disjoint from the vertical collar. The resulting no-connection condition gives compact disjoint critical-trajectory closures, by the exact Morse-block argument of [F4]: any noncompact limiting travel would break at a critical point, which would give an excluded connecting trajectory. The interior field change extends by zero on the protected collar.''','F2, F4, step 2.1, construct'),
 ('2.3',r'''The value-change step needs an additional orbit cutoff because the vertical height is not constant. In addition to the orbit-constant separating function $\beta$ of [F4], choose an orbit-constant $\alpha$ equal to one near both compact critical-trajectory sets and zero near the vertical product trajectories. Construct it on the lower exit level by a bump one near the compact critical exits and zero near its boundary, and extend it along regular trajectories. Near each critical-trajectory set extend it constantly as one. This is smooth by the same exit-continuity argument in the full proof of [F4]: close regular trajectories have exits near the compact critical exits, so the bump is already constant in a neighborhood. A local minimum has an attracting neighborhood with no lower through-exit, where the constant-one extension applies; reverse the argument for a maximum. Thus $d\alpha(X)=d\beta(X)=0$, with $\alpha=0$ on a neighborhood of the fixed vertical collar.''','F2, F4, step 2.2, construct'),
 ('2.4',r'''If the ordinary interchange formula in [F4] is $G(f,\beta)$, use $g=(1-\alpha)f+\alpha G(f,\beta)$ instead. Away from critical points, $dg(X)=(1-\alpha+\alpha\partial_1G(f,\beta))df(X)<0$. Near the critical sets $\alpha=1$, so this is precisely the desired value interchange and a constant change in each critical chart. Near the vertical face $\alpha=0$, so it is exactly $f$. Band-end identities make it smooth when extended by the old function. Finite adjacent exchanges sort the critical values by index; their inversion number strictly decreases. The boundary height, the field's product model and all endpoint maps are retained throughout.''','F4, step 2.3, algebra, construct'),
 ('3.1',r'''Assume now that the total bordism and both nonempty horizontal ends are connected. In index order the initial zero/one-handle graph has vertices the incoming component and new balls, and edges the one-handles. It is connected because handles of index at least two have connected attaching regions and cannot connect components. Root a spanning tree at the incoming vertex. Process its edges outward, absorbing each new ball with its incident one-handle by the local disk comparison of [F5]; carry every other attaching map through the resulting stage diffeomorphism. All attaching disks, arcs and comparison collars are compact in horizontal interiors, so the vertical collar is fixed. This removes all zero-handles.''','F5, step 2.1, step 2.4, construct'),
 ('3.2',r'''Reverse the presentation relative to the connected nonempty outgoing end and perform the same rooted-tree procedure. It deletes only index $d$ and paired index $d-1$ handles in the original direction and transports the rest, so it does not reintroduce removed zero-handles. The face charts and height reverse by $t\mapsto1-t$ during the construction and return to the prescribed ones afterward. This gives the claimed presentation without zero or top handles, retaining the full horizontal and vertical parametrizations. Steps 1.1–2.4 already establish the existence and rearrangement assertions without the connectivity assumptions used only for this deletion phase.''','F5, step 3.1, construct')
],r'''This retains the complete accepted fixed-height construction in `five-dimensional-common-middle-trace-construction.md`, Section 5, including the extra orbit-constant cutoff in the value interchange. All actual ordinary-triad existence, local handle-band, separation, interchange and rooted-tree supplier bodies were read; none is treated as already covering a nonconstant vertical boundary height. This is finite handle normalization, not a generic movie classification.''')

item(SURGERY,'Parametrized link-surgery existence for compact oriented three-manifolds',r'''Let $N,M$ be connected nonempty compact oriented smooth three-manifolds, with their boundaries identified with the same oriented surface $\Sigma$ in the bordism convention and with fixed compatible product collars. There is a finite framed link in $\operatorname{int}N$ whose surgery is diffeomorphic to $M$ with the prescribed external boundary parametrization. It may be realized as a four-dimensional two-handle trace with those marked horizontal faces and vertical collar $\Sigma\times[0,1]$. More generally this holds componentwise for a specified common component partition; empty input is treated by the empty union. In particular a fixed connected standard base with the required boundary may be chosen on each component, and a closed component may use $N=S^3$. An explicit connected standard base is the complement in $S^3$ of standard handlebodies placed in pairwise disjoint balls, one for each boundary component with its specified genus, with the given surface parametrizations attached to these boundary copies. This is relative surgery existence, not equivalence or completeness of surgery moves. Decorations may be carried by the resulting actual diffeomorphism; a complete decorated move theorem is a separate assertion.''',[
 '[['+OMEGA3+']] supplies a compact oriented smooth four-dimensional filling of every actual closed oriented three-manifold, retaining its marked cap submanifolds by the boundary identification.',
 '[['+MORSE+']] gives fixed-vertical-height relative handles and, for connected nonempty ends and connected total bordism, a presentation with no zero or top handles. [['+TRADE+']] changes an interior one-handle into a two-handle in dimension four while preserving the full boundary.',
 '[['+CIRCLE+']] supplies an explicit value/first-jet submersive polynomial family for perturbing curves in a three-manifold, including avoidance of any prescribed finite link. [['+ISO+']] compares full attaching-thickening isotopies relative to the incoming boundary.',
 '[['+COLLAR+']] supplies smooth collars and [['+ROUND+']] supplies collar-supported compatible seam roundings.'
],[
 ('1.1',r'''Glue $-N$ to $M$ along the actual given boundary map and collars, obtaining a closed oriented three-manifold $X$ with a marked seam $\Sigma$. By [F1] choose $U$ with $\partial U\cong X$ and pull back this marking. Discard filling components without boundary. If necessary join the remaining finitely many components by interior connected sums: remove two interior four-balls and join their oriented sphere boundaries by $S^3\times I$, using product annulus charts. These operations preserve every old boundary collar and make $U$ connected. Its boundary is nonempty, even when the seam is empty, since $N,M$ are nonempty.''','given, F1, F4, construct'),
 ('1.2',r'''Near the marked seam the filling has coordinates $\Sigma\times(-2\epsilon,2\epsilon)_u\times[0,2\epsilon)_v$, with $v$ inward. Remove a small notch along $u=v=0$: in this half-plane replace a small boundary interval by an inward compact arc with quadrant corners at its endpoints, unchanged outside a small rectangle. Its product with $\Sigma$ is the vertical face $\Sigma\times I$. Identify the shortened horizontal collars with the original ones by smooth increasing interval maps, identity near their far ends, and keep the identity on every $\Sigma$ point. Product quadrant charts retain the prescribed parametrizations at both corners. The notch does not disconnect the interior: each remaining local point joins the unchanged interior region. Thus this is a connected boundary-marked four-bordism from $N$ to $M$ with precisely the given vertical product collar. For empty $\Sigma$ no notch is needed.''','F1, F4, step 1.1, construct'),
 ('2.1',r'''Apply [F2] in dimension four to remove zero and four handles. Starting at connected $N$, trade every one-handle by its interior circle construction for a two-handle. Its feet lie in the same connected lower stage and the trade preserves connectedness as well as the whole boundary. Order handles by index using the fixed-height construction. Reverse from connected $M$ and trade the reversed one-handles, which were original three-handles, to two-handles. Reversing back leaves only two-handles. The modified four-manifold need not equal the original filling; its entire marked boundary does. Denote its resulting successive two-handle trace by $W'$.''','F2, step 1.2, construct'),
 ('3.1',r'''Record this successive trace by one link in the original $N$. Inductively suppose preceding handles are represented by a framed link $L\subset N$. The next attaching circle lies in the surgered outgoing three-manifold. Apply the explicit curve family in [F3] to perturb it off the finitely many belt-core circles of the filling solid tori: each core has codimension two whereas the curve source has dimension one. The perturbation is an attaching isotopy and carries its full normal thickening. Its compact intersection with each filling product $D^2\times S^1$ now has radial coordinate bounded below by some $\epsilon>0$.''','F3, step 2.1, construct'),
 ('3.2',r'''In each such product choose a smooth increasing radial reparametrization, identity near zero and outside a slightly larger seam collar, which sends every radius at least $\epsilon$ beyond the old filling-torus boundary. This exists by choosing its strictly positive derivative with the required integral and fixed end intervals. It is a radial ambient isotopy, stationary at its parameter ends. Thus the circle is pushed into the old exterior $N\setminus\nu L$. Carry its full attaching thickening by the derivative, shrinking it uniformly first if needed. By [F3] the isotopy extends over a collar of the existing trace, fixed at the incoming face and external boundary. Hence the total trace agrees with the prescribed successive one, retaining the outgoing comparison. The new circle is now an additional framed component in the original $N$. Finite induction produces a single link.''','F3, F4, step 3.1, construct'),
 ('4.1',r'''The outgoing boundary of a four-dimensional two-handle removes $S^1\times\operatorname{int}D^2$ and inserts $D^2\times S^1$ in its product attaching coordinates, exactly the stated framed surgery. Therefore the final link yields $M$ with the original external parametrization. For disconnected manifolds run the construction independently on each prescribed pair of connected components, using that pair's fixed base, and take their finite disjoint union. For empty inputs take the empty union. The common partition is essential: surgery never changes the number of ambient components. No nullhomotopy of attaching circles, fundamental-group restriction, Kirby completeness or decorated move completeness has been used.''','F4, step 3.2, construct')
],r'''This is the full existence construction of `five-dimensional-common-middle-trace-construction.md`, Section 6, with its actual boundary-marked filling input now discharged by the integral three-bounding theorem and an explicit connected-filling/notch construction. The single-link consolidation keeps complete framings and outgoing maps. It does not replace the native full relative-presentation theorem, whose global move-completion duty remains separate.''')

item(MIDDLE,'A boundary-marked five-bordism gives a common middle two-handle trace',r'''Let $N$ be a connected nonempty compact oriented three-manifold and let $W_0,W_1$ be connected four-dimensional finite two-handle traces from that same fixed base. Their full common boundary $Y$ and all horizontal, external and corner collar identifications are marked. Suppose a connected compact oriented five-bordism $V$ between them is supplied with its full vertical product collar $Y\times I$ fixed. Then finitely many O3 insertions on each original framed link give two descriptions of the same actual four-dimensional two-handle trace $W_*$ from $N$, with the full marked boundary retained. Here each O3 insertion is a framed knot and its small disk-framed zero meridian, with its actual boundary-relative identification. No condition on any fundamental group is required. In conjunction with the projective-plane stabilization supplier, split signed unit-framed unknot insertions first supply such a $V$ whenever needed. This is a common-middle existence assertion; it does not assert that the two descriptions of $W_*$ are related by a complete O2/O3 movie.''',[
 '[['+MORSE+']] supplies the fixed-height cornered relative handle presentation, top/zero deletion and index ordering for connected nonempty ends.',
 '[['+TRADE+']] gives the boundary-preserving one-to-three trade in dimension five and the actual four-dimensional framed-circle-surgery two-handle pair.',
 '[['+CIRCLE+']] moves every attaching framed circle in a four-dimensional two-handle trace into its fixed base avoiding the old attaching link, for arbitrary fundamental-group class and prescribed full framing.',
 '[['+O3+']] gives the boundary-relative O3 identification, fixing every old attaching link outside its small solid torus. [[lem-projective-plane-stabilization-gives-relative-five-bordisms]] supplies the actual connected fixed-collar five-bordism after split signed unit-framed-unknot insertions.'
],[
 ('1.1',r'''Apply [F1] to the supplied $V$ in dimension five, keeping the full marked vertical collar. Remove its zero and five handles. Trade each one-handle to a three-handle by [F2], using a joining arc in the connected lower stage. Reorder, reverse, and trade each reversed one-handle to a three-handle there; in the original direction these are trades of index four to index two. No zero, one, four or five handle is reintroduced. Sort the remaining two- and three-handles by the fixed-height construction [F1]. Choose the regular middle four-manifold $W_*$ after the two-handles and before the three-handles.''','given, F1, F2, construct'),
 ('1.2',r'''From $W_0$ to $W_*$ only five-dimensional two-handles occur. From $W_1$ the reversed three-handles have complementary index $5-3=2$, so the same is true. Every such handle changes its four-dimensional level by interior framed circle surgery. Interior surgery preserves connectedness: the tube boundary $S^1\times S^2$ is connected, so gluing the old tube back could not join different components of its complement; since the old level is connected, that complement is connected, and the replacement attaches along the same connected interface. Thus every level in this construction stays connected, as required to iterate the base-circle argument.''','F1, F2, step 1.1, construct'),
 ('2.1',r'''Start with either original link presentation of $W_i$. By [F3] move the first five-dimensional handle's attaching circle to the fixed base, retaining its rank-three framing through an integral level frame. Its base representative avoids the old link, so choose its small tube disjoint from every old attaching thickening. By [F2] the actual four-dimensional surgery is two added two-handles on the corresponding $K$ and disk-framed zero meridian $U$. By [F4] its induced O3 boundary map is identity on the old link and the external base collar. Hence every previous handle and both end parametrizations are carried correctly. The new level again has a finite two-handle presentation from the same base.''','F2, F3, F4, step 1.2, construct'),
 ('2.2',r'''Repeat step 2.1 for the finitely many five-dimensional two-handles from each end. At every stage the preceding conclusion gives exactly the hypothesis needed for [F3], so there is no circular assumption that an arbitrary four-manifold already has such a presentation. Both finite sequences terminate at the same actual level $W_*$ chosen in step 1.1, with its original full marked boundary, and give the stated two link descriptions. If no handles occur, the empty sequence is allowed.''','F3, step 1.1, step 2.1, construct'),
 ('3.1',r'''If an actual five-bordism was not initially supplied, [F4] first corrects the signature seam by interior connected sums with signed projective planes, represented by split $+1$ or $-1$ framed unknot insertions. It produces the required connected fixed-collar $V$, without a fundamental-group hypothesis. Apply steps 1.1–2.2 to these corrected traces. This adds precisely the asserted O1 preparation to the O3 common-middle construction. The conclusion leaves two descriptions of $W_*$; comparing them by an unrestricted trace-changing movie is a further theorem and is not inferred from their common diffeomorphism type.''','F4, step 2.2, construct')
],r'''This retains `five-dimensional-common-middle-trace-construction.md`, Section 7, with its circle input supplied by the separately packaged finite-dimensional construction. The actual projective-plane relative-five-bordism proof was read in full. Roberts' common-middle stage is the source context; no same-trace two-equivalence or decorated Kirby-completeness theorem is imported. The native full relative-presentation theorem remains a separate consumer of the global movie construction.''')

# Merge-ready contracts: each proposed supplier is read from OUT before canonical installation.
def section(raw,name):
 m=re.search(r'^## '+re.escape(name)+r'\s*\n([\s\S]*?)(?=^## |\Z)',raw,re.M)
 if not m:raise ValueError(name)
 return m[1].strip()
def source_path(id):
 local=OUT/(id+'.md')
 if local.exists():return local
 canonical=Path('items')/(id+'.md')
 if canonical.exists():return canonical
 sibling=BASE.parent/'oriented-four/proposed-items'/(id+'.md')
 if sibling.exists():return sibling
 raise FileNotFoundError(id)
contracts={}; receipts=[]
for p in ITEMS:
 raw=p.read_text();facts=dict(re.findall(r'^\[(F\d+)\] (.*)$',raw,re.M));steps=dict(re.findall(r'^(\d+\.\d+) (.*)$',raw,re.M))
 citations=[];input_rows=[]
 for f,t in facts.items():
  for sid in re.findall(r'\[\[([^]|]+)',t):
   sp=source_path(sid);sr=sp.read_text();sec='Statement' if '\n## Statement\n' in sr else 'Definition';quote=section(sr,sec)
   uses=[s for s,t in steps.items() if re.search(r'\b'+f+r'\b',t)]
   assert uses,(p.stem,f)
   citations.append(dict(fact=f,source=sid,source_section=sec,quote=quote,uses=uses))
   input_rows.append(dict(id=sid,path=str(sp),raw_sha256=hashlib.sha256(sp.read_bytes()).hexdigest()))
 derivations=[]
 for s,t in steps.items():
  refs=[]
  for m in re.finditer(r'\b(F\d+)\b|\bstep (\d+\.\d+)\b',t):
   v=m[1] or 'step '+m[2]
   if v not in refs:refs.append(v)
  derivations.append(dict(id='derivation-'+s,claim=t.split('. ')[0],step=s,inputs=refs or ['given']))
 final=list(steps)[-1]
 boundaries=[dict(case='empty',status='checked',evidence='Statement records the precise nonempty hypotheses; step '+final+' includes the permitted empty sequence or union.'),dict(case='zero',status='checked',evidence='Statement retains all boundary and framing data; step '+final+' covers the zero-handle-count endpoint of the construction.'),dict(case='one',status='checked',evidence='The single local construction is proved before finite iteration in step '+list(steps)[0]+'.'),dict(case='degenerate',status='checked',evidence='Statement imposes the connectedness, dimension and full-framing hypotheses used in step '+final+'.'),dict(case='endpoints',status='checked',evidence='All endpoint and external collar identifications are retained as asserted in the Statement and step '+final+'.'),dict(case='nonempty-choice',status='checked',evidence='AC and the nonempty source and connected-stage conditions are explicit in the Statement; step '+final+' closes the construction.'),dict(case='iff-forward',status='not_applicable',reason='The Statement is a constructive existence implication, not an equivalence.'),dict(case='iff-reverse',status='not_applicable',reason='The Statement is a constructive existence implication, not an equivalence.')]
 contracts[p.stem]=dict(citations=citations,derivations=derivations,routine_steps=[],boundaries=boundaries)
 receipts.append(dict(id=p.stem,path=str(p),raw_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),facts_section_exact=section(raw,'Facts & Assumptions'),inputs=input_rows))
(OUT/'trace-prerequisites-proof-contract-payload.json').write_text(json.dumps(dict(version=1,scope=list(contracts),contracts=contracts),indent=2)+'\n')
(OUT/'trace-prerequisites-packaging-receipt.json').write_text(json.dumps(dict(version=1,scope=list(contracts),items=receipts,claim='Proposed carriers and merge-ready payload; no canonical install, strict gate or publication claim.'),indent=2)+'\n')
print('Packaged',len(ITEMS),'items and merge-ready contracts')
